-- READ ONLY. Narrow metadata for Customer Configuration/import release planning.
select jsonb_build_object(
 'tables',(select jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl::text) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and (c.relname in ('jobs','app_users','app_role_capabilities','production_companies','production_contacts') or c.relname ~ '^(customers|companies|contacts|customer_contacts|job_contacts)$')),
 'columns',(select jsonb_agg(jsonb_build_object('table',table_name,'name',column_name,'type',data_type,'udt',udt_name,'nullable',is_nullable,'default',column_default) order by table_name,ordinal_position) from information_schema.columns where table_schema='public' and table_name in ('jobs','app_users','production_companies','production_contacts')),
 'policies',(select jsonb_agg(to_jsonb(p) order by tablename,policyname) from pg_policies p where schemaname='public' and tablename in ('jobs','app_users','app_role_capabilities','production_companies','production_contacts')),
 'grants',(select jsonb_agg(to_jsonb(g) order by table_name,grantee,privilege_type) from information_schema.role_table_grants g where table_schema='public' and table_name in ('jobs','app_users','app_role_capabilities','production_companies','production_contacts')),
 'capabilities',(select jsonb_agg(jsonb_build_array(role,capability) order by role,capability) from public.app_role_capabilities where capability in ('readOperationalData','writeBusinessData','createProductionJob','editProductionJobRoutine','editProductionJobDetails','scheduleProduction','manageUsers')),
 'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'identity',pg_get_function_identity_arguments(p.oid),'definition',pg_get_functiondef(p.oid),'security_definer',p.prosecdef,'owner',pg_get_userbyid(p.proowner),'config',p.proconfig,'acl',p.proacl::text) order by p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('has_app_capability','require_app_capability','guard_tenops_business_write','get_my_app_access','can_manage_production_contacts','search_production_customers','save_production_customer','archive_production_customer')),
 'job_constraints',(select jsonb_agg(jsonb_build_object('name',conname,'definition',pg_get_constraintdef(oid)) order by conname) from pg_constraint where conrelid='public.jobs'::regclass),
 'job_triggers',(select jsonb_agg(jsonb_build_object('name',t.tgname,'definition',pg_get_triggerdef(t.oid),'function',p.proname,'function_definition',pg_get_functiondef(p.oid)) order by t.tgname) from pg_trigger t join pg_proc p on p.oid=t.tgfoid where t.tgrelid='public.jobs'::regclass and not t.tgisinternal),
 'migrations',(select jsonb_agg(jsonb_build_object('version',version,'name',name) order by version) from supabase_migrations.schema_migrations)
) as customer_import_compatibility;
